-- Official E8 Terminal Hyperliquid book (rows 73–380).
-- Native HL_PERP + HIP-3 Trade.XYZ only. Unowned public catalog.
create table if not exists tradable_assets (
  id               serial primary key,
  terminal_symbol  text not null unique,
  ticker           text not null,
  hl               text not null,
  dex              text not null,
  venue            text not null,
  name             text not null,
  asset_class      text not null,
  e8_asset_class   text not null,
  book             text not null,
  quote_asset      text not null default 'USD',
  max_leverage     integer not null,
  price_precision  integer not null,
  size_precision   integer not null,
  min_size         numeric not null,
  tick_size        numeric not null,
  trading_hours    text not null,
  terminal_url     text not null
);
create index if not exists tradable_assets_ticker_idx on tradable_assets (ticker);
create index if not exists tradable_assets_book_idx on tradable_assets (book);

insert into tradable_assets (
